/* Capa de RELATÓRIO DE TECNOLOGIA — os elementos da capa que o time já usa.
 *
 * Os selos e a assinatura são RECORTADOS DA PÁGINA RENDERIZADA, e não extraídos
 * como objeto: no PDF eles guardam a transparência num SMask separado, e extrair
 * o objeto trazia o fundo preto junto — foi o retângulo preto que apareceu na
 * primeira versão da capa. Recortados da página, já vêm compostos sobre o fundo
 * escuro, que é exatamente como aparecem ali.
 *
 * As proporções são as MEDIDAS NA PÁGINA, e não as da caixa do objeto: os selos
 * são 90x46pt (largos), e forçá-los num quadrado os esticava.
 *
 * Ficam em arquivo separado, e não dentro de apresentacao.js, por um motivo
 * prático: é base64 que ninguém precisa reler ao mexer na lógica dos slides — e o
 * navegador guarda este arquivo em cache entre as gerações.
 */
window.CAPA_TECNOLOGIA = {
  fundo: 'data:image/jpeg;base64,',
  selos: 'data:image/png;base64,',
  logo: 'data:image/png;base64,',
  // Posição e tamanho em polegadas, convertidos da capa original (960x540pt,
  // divisor 96) e medidos na página renderizada.
  selosPos: { x: 8.58, y: 0.40, w: 0.94, h: 0.48 },
  logoPos:  { x: 8.13, y: 4.83, w: 1.41, h: 0.52 },
  verde: '00FD54',
};
